function H(p,i,{partition:u=!0}={}){const h=new Map;for(const t of p){const e=u?t.r.candidates[0].party:"全部地區";h.has(e)||h.set(e,[]),h.get(e).push({...t})}const a=[...h].map(([t,e])=>({party:t,nodes:e.sort((s,r)=>r.radius-s.radius),votes:e.reduce((s,r)=>s+r.r.total,0)})).sort((t,e)=>e.votes-t.votes);if(!a.length)return[];const l=u?34:0,o=u?20:0,n=Math.max(1,i.width-o*(a.length-1)),x=Math.min(110,n/a.length*.7),F=a.reduce((t,e)=>t+e.votes,0),y=Math.max(1,i.height-l);for(const t of a)t.width=x+(n-x*a.length)*t.votes/F;function m(t,e,s=!1){let r=0,w=0,d=0;for(const g of t.nodes){const b=g.radius*e,f=b*2+6;if(f>t.width)return 1/0;r&&r+f>t.width&&(w+=d,r=0,d=0),d=Math.max(d,f),s&&(g.x=r+f/2,g.y=w+d/2,g.radius=b),r+=f}return w+d}let c=0,M=Math.max(i.width,i.height)/70;for(let t=0;t<28;t++){const e=(c+M)/2;a.every(s=>m(s,e)<=y)?c=e:M=e}let v=i.x;const k=[];for(const t of a){const e=m(t,c);m(t,c,!0);for(const s of t.nodes)s.x+=v,s.y+=i.y+l+(y-e)/2,s.groupX=v+t.width/2,k.push(s);v+=t.width+o}return k}function V(p){const i=p.filter(o=>Number.isFinite(o.total)&&o.total>0).slice().sort((o,n)=>n.total-o.total),u=i.reduce((o,n)=>o+n.total,0);let h=0,a=0;const l=i.map((o,n)=>(h+=o.total,!a&&h>=u/2&&(a=n+1),{r:o,rank:n+1,share:o.total/u*100,cumulative:h/u*100}));return{rows:l,total:u,halfCount:a,topFive:l[Math.min(4,l.length-1)]?.cumulative||0}}export{H as p,V as r};
